# Let me analyze the relationship between 4s and 7s more carefully
# Check if there's a count of 4s adjacent to 7s that could determine what to replace 7s with

def get_neighbors_4(r, c, grid):
    """Count 4s in the 8 neighbors of position (r,c)"""
    count = 0
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == 4:
                    count += 1
    return count

